let activatedAt=0;window.addEventListener('pagehide',saveDesk);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&user&&!document.querySelector('dialog[open]')&&Date.now()-activatedAt>15000){activatedAt=Date.now();refresh();}});
function updateRentalPrice(){
 const f=$('#issue-form'),equipment=f.elements.equipment.value,rate=data.fleet.find(i=>i.id===equipment)?.price,units=Number(equipment==='big'?f.elements.people.value:f.elements.quantity.value),minutes=(Date.parse(f.elements.expectedReturn.value+':00+03:00')-Date.parse(f.elements.departed.value+':00+03:00'))/60000;
 $('#issue-people-label').hidden=equipment!=='big';
 if(rentalPricePlan!=='hour'){$('#issue-status').textContent=rentalPricePlan==='day'?'Безлимит на день: укажите фактически полученную сумму по дневному тарифу.':rentalPricePlan==='takeaway'?'САП с собой: укажите фактически полученную сумму за согласованный срок, без возвратного залога.':'Бронь: укажите фактически полученную сумму по согласованному тарифу.';return;}
 if(Number.isFinite(rate)&&Number.isInteger(units)&&units>0&&Number.isFinite(minutes)&&minutes>0){const cents=Math.round(rate*100*units*minutes/60);if(!rentalPriceManual)f.elements.amount.value=(cents/100).toFixed(2);$('#issue-status').textContent=rentalPriceManual?'Сумма задана вручную. По тарифу: '+money(cents)+'.':'По тарифу · сумму можно изменить вручную.';}
 else{if(!rentalPriceManual)f.elements.amount.value='';$('#issue-status').textContent='Укажите время и количество для расчёта.';}
}
for(const name of ['equipment','quantity','people','departed','expectedReturn'])$('#issue-form').elements[name].addEventListener('change',()=>{updateRentalPrice();saveRentalDraft();});
$('#issue-form').elements.amount.addEventListener('input',()=>{rentalPriceManual=$('#issue-form').elements.amount.value.trim()!=='';saveRentalDraft();});
$('#issue-form').elements.amount.addEventListener('change',()=>{updateRentalPrice();saveRentalDraft();});
for(const b of document.querySelectorAll('[data-duration]'))b.onclick=()=>{const f=$('#issue-form');if(!f.elements.departed.value){$('#issue-status').textContent='Укажите время отплытия.';return;}f.elements.expectedReturn.value=new Date(Date.parse(f.elements.departed.value+':00+03:00')+Number(b.dataset.duration)*60000+10800000).toISOString().slice(0,16);updateRentalPrice();saveRentalDraft();};
$('#discard-draft').onclick=()=>{sessionStorage.removeItem('rental-draft-'+user.id);$('#issue-dialog').close();openIssue(false);};

const account=$('body>header');$('[data-desk-pane=more]').append(account);

function renderDayRentals(){
 const out=$('#rental-history-list');if(!out||!data||out.querySelector('.refund-panel[open]'))return;$('#rental-history-day').value=$('#report-day').value;
 const openIds=new Set([...out.querySelectorAll('details[open]')].map(e=>e.dataset.id));const rows=(data.dayRentals||[]).filter(r=>(historyFilter==='all'||(historyFilter==='returned'?r.returned:!r.returned))&&Desk.matches(r,activeQuery,data.fleet));out.replaceChildren();$('#rental-history-count').textContent=rows.length+' записей';
 for(const r of rows){const row=text('details','','history-rental'),summary=text('summary'),label=r.custom_json?JSON.parse(r.custom_json).title:(data.fleet.find(f=>f.id===r.equipment)?.label||r.equipment);row.dataset.id=String(r.id);row.open=openIds.has(String(r.id));summary.append(text('strong',label+(r.quantity>1?' × '+r.quantity:'')),text('span',r.name),text('small',r.initial_due<0?'Отменено до выдачи · '+shortTime(r.created):r.initial_due>0?'Ожидает оплаты · '+shortTime(r.created):r.custom_json?'Продажа · '+shortTime(r.created):r.returned?'Возвращено · '+shortTime(r.returned):'На воде · до '+shortTime(r.expected_return)));row.append(summary);const details=text('div','','history-rental-details');details.append(text('span','Выдано: '+time(r.departed+':00+03:00')),text('span','Телефон: '+r.phone),text('span','Оплата: '+money(r.paid)));if(r.initial_due>0){const pay=text('button','Оплатить на CS50');pay.onclick=()=>startRentalPayment(r.id,'issue');details.append(pay);}else if(r.returned)details.append(text('span','Возвращено: '+time(r.returned)));else{const b=text('button');setReturnButton(b,r);b.onclick=()=>returnRental(r.id,b);if(r.extension_due)details.append(text('strong','К доплате при возврате: '+money(r.extension_due)));details.append(b);}window.STARTRefunds?.mount(card,'rental',r.id,user.id,refresh);if(user.role==='admin'&&!r.custom_json){const b=text('button','Исправить / история');b.onclick=()=>openEdit(r);details.append(b);}row.append(details);out.append(row);}
 if(!rows.length)out.append(text('p',activeQuery?'Ничего не найдено.':historyFilter==='returned'?'Возвратов за эту дату нет.':'Аренд за эту дату нет.','empty'));
}
$('#rental-history-day').onchange=()=>{$('#report-day').value=$('#rental-history-day').value;saveDesk();refresh();};
$('#rental-history-filter').onchange=e=>{historyFilter=e.target.value;renderDayRentals();saveDesk();};
$('#rental-history-refresh').onclick=refresh;

// POS workspace: use existing routes and mutations, no parallel booking/order model.
let cafeAttention=[],cafeLoading=false,cafeLast=0;
function renderCafeAttention(){
 const out=$('#desk-cafe-list');if(!out)return;out.replaceChildren();
 const labels={NEW:'В работе',READY:'Готов к выдаче',ACCEPTED:'В работе',COOKING:'В работе'};
 for(const r of cafeAttention.slice(0,3)){
  const row=text('div','','cafe-attention-row'),content=text('div'),link=text('a');link.href='/admin/cafe/#order-'+r.id;
  const place=r.details.place?.name||r.details.location||(r.details.fulfillment==='lounge'?'Место позже':r.details.fulfillment==='pickup'?'В кафе':'На яхту');
  link.append(text('strong','№'+r.id+' · '+place));content.append(link,text('p',labels[r.status]+' · ждёт '+Math.max(0,Math.floor((serverNow()-r.created)/60000))+' мин','cafe-attention-state'+(r.status==='READY'?' ready':'')),text('p',r.details.items.map(i=>i.quantity+'× '+i.name).join(', ')+' · '+money(r.total_cents)));
  row.append(content);const next=['NEW','ACCEPTED','COOKING','READY'].includes(r.status)?'DELIVERED':null;
  if(next){const b=text('button','Выполнен');b.setAttribute('aria-label','Выполнен заказ №'+r.id);b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await api('cafe/status',{id:r.id,revision:r.revision,status:next});document.dispatchEvent(new Event('station-updated'));await loadCafeAttention(true);}catch(e){notice(e.message);await loadCafeAttention(true);}finally{b.disabled=false;}};if(next==='DELIVERED')content.append(text('p',r.details.terminalPaidAt?'Оплачен':r.details.terminalPaymentRequired?'Ожидает оплаты на кассе':'Оплата при получении'));row.append(b);}out.append(row);
 }
 if(!cafeAttention.length)out.append(text('p','Нет заказов, требующих внимания','empty'));

}
async function loadCafeAttention(force=false){if(!user||document.hidden||cafeLoading||(!force&&Date.now()-cafeLast<15000))return;cafeLoading=true;try{const d=await api('cafe/orders?compact=1&date='+localTime().slice(0,10));cafeAttention=d.rows.filter(r=>['NEW','ACCEPTED','COOKING','READY'].includes(r.status)).sort((a,b)=>a.created-b.created);cafeLast=Date.now();renderCafeAttention();}catch(e){$('#desk-cafe-list').replaceChildren(text('p','Не удалось обновить заказы. Откройте кафе.','empty'));}finally{cafeLoading=false;}}
$('#open-cash').onclick=async()=>{switchDesk('more');const fold=$('#shift-content').closest('details');fold.open=true;await loadShift();fold.scrollIntoView({block:'start',behavior:'instant'});};
function updateDeskDate(){$('#desk-date').textContent=new Date().toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'});}
async function cashState(){if(!user||document.hidden)return;try{const s=await api('shift?day='+localTime().slice(0,10));$('#cash-state').textContent=s.current?(s.current.closed_at?'Итог дня сохранён':'Рабочий день начат'):'Рабочий день ещё не начат';$('#cash-state').classList.toggle('open',!!s.current&&!s.current.closed_at);}catch{$('#cash-state').textContent='Касса: нет свежих данных';}}
document.addEventListener('station-updated',()=>{loadCafeAttention(true);cashState();});document.addEventListener('desk-sync',e=>{if(e.detail.ok){loadCafeAttention();cashState();}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!document.querySelector('dialog[open]')&&!$('#workspace').hidden){e.preventDefault();$('#active-search').focus();$('#active-search').select();}if(e.key==='Escape'&&document.activeElement===$('#active-search'))$('#clear-active-search').click();});
window.addEventListener('hashchange',()=>{if(location.hash==='#work')switchDesk('work');});if(location.hash==='#work')switchDesk('work');
updateDeskDate();setInterval(()=>{if(!document.hidden){updateDeskDate();loadCafeAttention();renderCafeAttention();}},30000);

// Manual services are completed sales; they do not reserve rental equipment.
if($('#manual-sale')){
 const d=document.createElement('dialog');d.innerHTML='<form><h2>Свободная цена</h2><label>Товар или услуга<input name="title" maxlength="120" required></label><label>Цена за единицу, ₽<input name="price" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required></label><label>Количество<input name="quantity" type="number" min="1" max="1000" step="1" value="1" required></label><p>Продажа без выдачи техники.</p><button type="submit">Принять оплату</button> <button type="button" data-close>Закрыть</button><p role="alert"></p></form>';document.body.append(d);let pending=null,sending=false;const pendingKey=()=> 'manual-sale-pending-'+user?.id;const persist=()=>{try{if(pending)sessionStorage.setItem(pendingKey(),JSON.stringify(pending));else sessionStorage.removeItem(pendingKey());}catch{}};
 $('#manual-sale').onclick=()=>{try{pending=JSON.parse(sessionStorage.getItem(pendingKey())||'null');}catch{}const f=d.querySelector('form');if(!pending)f.reset();else{f.elements.title.value=pending.title;f.elements.price.value=(pending.unitCents/100).toFixed(2);f.elements.quantity.value=pending.quantity;}for(const x of f.querySelectorAll('input'))x.disabled=!!pending;f.querySelector('[role=alert]').textContent=pending?'Проверьте предыдущую отправку повторным нажатием.':'';d.showModal();};d.querySelector('[data-close]').onclick=()=>d.close();
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(sending)return;const f=e.currentTarget,parts=f.elements.price.value.replace(',','.').split('.');if(!pending)pending={requestId:crypto.randomUUID(),title:f.elements.title.value.trim(),quantity:Number(f.elements.quantity.value),unitCents:Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'))};persist();sending=true;for(const x of f.querySelectorAll('input,button[type=submit]'))x.disabled=true;try{const r=await fetch('/api/admin/manual-sale',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pending)}),b=await r.json();if(!r.ok){if(r.status<500)pending=null;throw new Error(b.error||'Не удалось сохранить');}pending=null;d.close();await refresh();if(data.pendingRentals?.some(r=>r.id===b.id))await startRentalPayment(b.id,'issue');else notice('Продажа сохранена');}catch(err){f.querySelector('[role=alert]').textContent=err.message+(pending?' Повторите отправку: повторная продажа не создастся.':'');}finally{persist();sending=false;for(const x of f.querySelectorAll('input'))x.disabled=!!pending;f.querySelector('[type=submit]').disabled=false;}};
}
